use super::*;

#[derive(serde::Deserialize)]
struct Reference {
    lower: f64,
    upper: f64,
    alpha: f64,
    beta: f64,
    counts: [u64; 5],
    llr: f64,
    estimate: Option<[f64; 3]>,
}

#[derive(serde::Deserialize)]
struct Fixtures {
    cases: Vec<Reference>,
}

#[test]
fn matches_fishtest_reference() {
    // Generated by the unmodified functions and revision recorded in the fixture.
    let fixtures: Fixtures =
        serde_json::from_str(include_str!("../../tests/fishtest-reference.json")).unwrap();
    for reference in fixtures.cases {
        let config = Config {
            lower_elo: reference.lower,
            upper_elo: reference.upper,
            alpha: reference.alpha,
            beta: reference.beta,
        };
        let context = format!(
            "[{}, {}] {:?}",
            reference.lower, reference.upper, reference.counts
        );
        let llr = config.llr(reference.counts).unwrap();
        assert!(
            (llr - reference.llr).abs() < 1e-5,
            "LLR {context}: {llr} != {}",
            reference.llr
        );
        let (lower, upper) = config.boundaries();
        let verdict = |value| {
            if value <= lower {
                -1
            } else if value >= upper {
                1
            } else {
                0
            }
        };
        assert_eq!(verdict(llr), verdict(reference.llr), "{context}");
        match (config.estimate(reference.counts), reference.estimate) {
            (Some(actual), Some(expected)) => {
                for (actual, expected) in [actual.elo, actual.interval[0], actual.interval[1]]
                    .into_iter()
                    .zip(expected)
                {
                    assert!(
                        (actual - expected).abs() < 1e-5,
                        "estimate {context}: {actual} != {expected}"
                    );
                }
            }
            (None, None) => {}
            _ => panic!("missing estimate {context}"),
        }
    }
}

#[test]
fn validates_config_and_handles_no_results() {
    let mut config = Config {
        lower_elo: 0.,
        upper_elo: 20.,
        alpha: 0.05,
        beta: 0.05,
    };
    assert!(config.validate());
    assert_eq!(config.llr([0; 5]).unwrap(), 0.0);
    assert!(config.estimate([0; 5]).is_none());
    assert!(config.estimate([0, 0, 1, 0, 0]).is_none());
    config.upper_elo = 0.;
    assert!(!config.validate());
    config.upper_elo = f64::NAN;
    assert!(!config.validate());
    config.upper_elo = 20.;
    config.alpha = 0.;
    assert!(!config.validate());
}
